package com.epsilon.cfr.model;

import ai.djl.Device;
import com.epsilon.ai.decision.EpsilonUtilityProfile;
import com.epsilon.cfr.collection.DecisionContext;
import com.epsilon.cfr.data.CfrSampleId;
import com.epsilon.cfr.data.CfrTrainingRow;
import com.epsilon.config.settings.DecisionComputePrecision;
import com.epsilon.config.settings.DecisionTensorTransfer;
import com.epsilon.engine.GameEngine;
import com.epsilon.engine.GameStepResult;
import com.google.gson.GsonBuilder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** 整理前後のモデルを同じチェックポイントから検証する、実験領域だけのCPU比較。 */
public final class CheckpointParityProbe {
  public static void main(String[] arguments) throws Exception {
    String command = arguments[0];
    Path input = Path.of(arguments[1]);
    Path output = Path.of(arguments[2]);
    Files.createDirectories(output);
    var contexts = new ArrayList<DecisionContext>();
    var rows = new ArrayList<CfrTrainingRow>();
    for (int index = 0; index < 6; index++) {
      long seed = 19100L + index;
      var engine = new GameEngine(seed);
      var boundary = (GameStepResult.AwaitingDecisions) engine.stepHanchan();
      var point = boundary.decisions().getFirst();
      int count = index % 3 == 0 ? 1 : index % 3 == 1 ? 2 : point.legalActions().size();
      var context = new DecisionContext(seed, point.id(), point.player(),
          engine.observation(point.player()), point.legalActions().subList(0, count));
      contexts.add(context);
      int[] actions = context.legalActions().stream().mapToInt(action -> action.toIndex()).toArray();
      double[] policy = new double[actions.length];
      for (int action = 0; action < policy.length; action++)
        policy[action] = (action + 1d) / (policy.length * (policy.length + 1d) / 2d);
      rows.add(new CfrTrainingRow(new CfrSampleId(1, seed, point.id(), point.player()),
          actions, index % count, policy, .1 * (index + 1), 0, 0,
          CfrObservationCodec.encodePayload(context)));
    }
    // 同一抽選の再出現も含め、更新時の重複集約を通す。
    rows.add(rows.get(1));
    rows.add(rows.get(1));
    var result = new LinkedHashMap<String, Object>();
    for (var role : CfrModel.Role.values()) {
      var config = new CfrModelConfig(16, 2, .002f, .01f, .001f, 1337,
          2, DecisionComputePrecision.FLOAT32, DecisionTensorTransfer.DIRECT_BUFFER,
          EpsilonUtilityProfile.TENHOU);
      try (CfrModel model = command.equals("create")
          ? new CfrModel(config, role, Device.cpu())
          : CfrModel.loadTraining(input.resolve(role.name()), Device.cpu())) {
        if (command.equals("create")) {
          model.train(rows);
          model.train(rows);
          model.saveTraining(output.resolve(role.name()));
          result.put(role.name(), checkpoint(model, rows, contexts, output.resolve(role.name())));
        } else {
          var steps = new ArrayList<Object>();
          for (int step = 0; step <= 3; step++) {
            var entry = new LinkedHashMap<String, Object>();
            if (step > 0) entry.put("metrics", model.train(rows));
            Path directory = output.resolve(role.name()).resolve("step-" + step);
            model.saveTraining(directory);
            entry.putAll(checkpoint(model, rows, contexts, directory));
            steps.add(entry);
          }
          result.put(role.name(), steps);
        }
      }
    }
    Files.writeString(output.resolve("result.json"),
        new GsonBuilder().setPrettyPrinting().create().toJson(result));
  }

  private static Map<String, Object> checkpoint(CfrModel model, List<CfrTrainingRow> rows,
      List<DecisionContext> contexts, Path directory) throws Exception {
    var result = new LinkedHashMap<String, Object>();
    result.put("parameterNames", model.parameterNames());
    result.put("updates", model.updates());
    result.put("weightsSha256", HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
        .digest(Files.readAllBytes(directory.resolve("weights.bin")))));
    result.put("scores", rows.stream().map(row -> model.rawScores(row.observation())).toList());
    result.put("policies", model.evaluate(contexts).stream().map(prediction -> prediction.targetPolicy()).toList());
    return result;
  }
}
